import{_ as a,o as t,c as r,a2 as i}from"./chunks/framework.BbQUUm7J.js";const u=JSON.parse('{"title":"Developer Compliance Invariants","description":"","frontmatter":{},"headers":[],"relativePath":"compliance/invariants.md","filePath":"compliance/invariants.md","lastUpdated":1794859264000}'),n={name:"compliance/invariants.md"};function o(s,e,l,c,d,p){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="developer-compliance-invariants" tabindex="-1">Developer Compliance Invariants <a class="header-anchor" href="#developer-compliance-invariants" aria-label="Permalink to &quot;Developer Compliance Invariants&quot;">​</a></h1><p>Non-negotiable rules for anyone building on or extending this CLI. Every one of them is enforced in code today — regressions fail tests.</p><h2 id="_1-never-bypass-sep-8-verification" tabindex="-1">1. Never bypass SEP-8 verification <a class="header-anchor" href="#_1-never-bypass-sep-8-verification" aria-label="Permalink to &quot;1. Never bypass SEP-8 verification&quot;">​</a></h2><p>Client code must never simulate or fabricate SEP-8 issuer approval. If an issuer approval server is unreachable, the transaction <strong>fails closed</strong>. <code>rwa kyc</code> exits non-zero with guidance; regulated-asset results carry <code>sep8Status: &quot;not_performed&quot;</code>.</p><h2 id="_2-never-claim-retail-perpetual-availability-in-the-us" tabindex="-1">2. Never claim retail perpetual availability in the US <a class="header-anchor" href="#_2-never-claim-retail-perpetual-availability-in-the-us" aria-label="Permalink to &quot;2. Never claim retail perpetual availability in the US&quot;">​</a></h2><p>All documentation, help text and marketing must state that derivatives and margin shorting are restricted to verified non-US persons or qualified Eligible Contract Participants (7 U.S.C. § 1a(18)). The CLI surfaces this in <code>furlpay short mechanisms</code>.</p><h2 id="_3-never-output-plaintext-payment-card-credentials" tabindex="-1">3. Never output plaintext payment card credentials <a class="header-anchor" href="#_3-never-output-plaintext-payment-card-credentials" aria-label="Permalink to &quot;3. Never output plaintext payment card credentials&quot;">​</a></h2><p>PAN and CVV never appear in terminal output, command history or persistent logs.</p><h2 id="_4-enforce-the-travel-rule-at-the-protocol-level" tabindex="-1">4. Enforce the Travel Rule at the protocol level <a class="header-anchor" href="#_4-enforce-the-travel-rule-at-the-protocol-level" aria-label="Permalink to &quot;4. Enforce the Travel Rule at the protocol level&quot;">​</a></h2><p>Cross-chain bridges and stablecoin transfers above $3,000 (€1,000 EU) must integrate encrypted IVMS101 counterparty-VASP exchange <strong>before</strong> on-chain execution.</p><h2 id="_5-keep-local-tools-and-hosted-services-strictly-separated" tabindex="-1">5. Keep local tools and hosted services strictly separated <a class="header-anchor" href="#_5-keep-local-tools-and-hosted-services-strictly-separated" aria-label="Permalink to &quot;5. Keep local tools and hosted services strictly separated&quot;">​</a></h2><p>Where the CLI is a pure client, maintain decentralized RPC paths. Where it touches platform APIs, require authenticated KYC/KYB session tokens. The session cookie is read-only and can never sign.</p><h2 id="engineering-corollaries-already-in-the-codebase" tabindex="-1">Engineering corollaries already in the codebase <a class="header-anchor" href="#engineering-corollaries-already-in-the-codebase" aria-label="Permalink to &quot;Engineering corollaries already in the codebase&quot;">​</a></h2><ul><li><strong>Zero fabricated hashes</strong> — missing exchange tx hash → <code>PENDING_CONFIRMATION</code>, never a synthetic id; escrow fund/release require a real <code>--tx-hash</code></li><li><strong>Fail closed on missing config</strong> — no signer, no agent policy, unreachable approval server: refuse</li><li><strong>Honesty labels at runtime</strong> — every simulated surface says <code>SIMULATED</code> / <code>LOCAL_SIMULATION</code> / <code>simulated: true</code> in its structured output</li><li><strong>Whitelist receipt fields</strong> — structured receipts copy known fields only; secrets can&#39;t ride along</li><li><strong>Integer money math</strong> — BigInt cents / fixed-point; audited ceilings on amounts; correct negative-sign handling</li><li><strong>Stable idempotency</strong> — header + body key per payment intent; unknown outcomes reconcile, never auto-retry under a new key</li><li><strong>Atomic spend ledgers</strong> — OS-file-locked validate-and-record under one lock; daily rollover at 00:00 UTC; no policy → refusal</li><li><strong>Credential-attachment allowlist</strong> — the session cookie goes only to <code>furlpay.com</code> over TLS or loopback</li></ul>',14)])])}const v=a(n,[["render",o]]);export{u as __pageData,v as default};
